@@ -0,0 +1,309 @@
+package eval
+
+import (
+	"bytes"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"sort"
+	"strings"
+	"time"
+)
+
+// A repeat dataset is the small, local-first benchmark used to learn how a
+// reviewer behaves on code you have access to, run several times per case.
+// It differs from Dataset in three ways: the repository may be private (only
+// commit identities are recorded, never source), a case may be "clean" (no
+// bug; any finding is noise), and the same case is run more than once so
+// run-to-run variance is measured instead of hidden.
+type RepeatDataset struct {
+	Version int          `json:"version"`
+	Cases   []RepeatCase `json:"cases"`
+}
+
+type RepeatCase struct {
+	ID         string  `json:"id"`
+	Kind       string  `json:"kind"` // seeded, historical, or clean
+	Repository string  `json:"repository,omitempty"`
+	BaseSHA    string  `json:"base_sha"`
+	HeadSHA    string  `json:"head_sha"`
+	Labels     []Label `json:"labels,omitempty"`
+	Notes      string  `json:"notes,omitempty"`
+}
+
+func DecodeRepeat(data []byte) (RepeatDataset, error) {
+	decoder := json.NewDecoder(bytes.NewReader(data))
+	decoder.DisallowUnknownFields()
+	var dataset RepeatDataset
+	if err := decoder.Decode(&dataset); err != nil {
+		return RepeatDataset{}, fmt.Errorf("decode eval cases: %w", err)
+	}
+	var extra any
+	if err := decoder.Decode(&extra); err != io.EOF {
+		return RepeatDataset{}, errors.New("eval cases contain trailing data")
+	}
+	return dataset, dataset.Validate()
+}
+
+func (d RepeatDataset) Validate() error {
+	if d.Version != 1 {
+		return errors.New("eval cases version must be 1")
+	}
+	if len(d.Cases) == 0 {
+		return errors.New("eval cases need at least one case")
+	}
+	seen := map[string]bool{}
+	for i, c := range d.Cases {
+		if c.ID == "" || seen[c.ID] {
+			return fmt.Errorf("case %d has a missing or duplicate ID", i)
+		}
+		seen[c.ID] = true
+		if !sha(c.BaseSHA) || !sha(c.HeadSHA) || c.BaseSHA == c.HeadSHA {
+			return fmt.Errorf("case %s needs distinct full base and head SHAs", c.ID)
+		}
+		switch c.Kind {
+		case "seeded", "historical":
+			if len(c.Labels) == 0 {
+				return fmt.Errorf("%s case %s needs at least one bug label", c.Kind, c.ID)
+			}
+		case "clean":
+			if len(c.Labels) != 0 {
+				return fmt.Errorf("clean case %s must have no labels", c.ID)
+			}
+		default:
+			return fmt.Errorf("case %s has unsupported kind %q", c.ID, c.Kind)
+		}
+		for _, label := range c.Labels {
+			if label.Path == "" || label.StartLine <= 0 || label.EndLine < label.StartLine {
+				return fmt.Errorf("case %s has an invalid label", c.ID)
+			}
+		}
+	}
+	return nil
+}
+
+// RunResult is one review of one case. A run that failed is recorded with its
+// error and left out of every score, so an outage never looks like a miss.
+type RunResult struct {
+	CaseID       string
+	Run          int
+	Findings     []Finding
+	CostMicrousd int64
+	Latency      time.Duration
+	Error        string
+}
+
+// MatchOptions decides when a finding counts as the labelled bug. Models
+// rarely land on the exact lines a human labelled, so a small slack is allowed;
+// the bug class is ignored unless a dataset uses the reviewer's own classes.
+type MatchOptions struct {
+	LineSlack    int
+	RequireClass bool
+}
+
+func (o MatchOptions) matches(f Finding, l Label) bool {
+	slack := o.LineSlack
+	if slack < 0 {
+		slack = 0
+	}
+	if f.Path != l.Path || f.StartLine > l.EndLine+slack || l.StartLine > f.EndLine+slack {
+		return false
+	}
+	return !o.RequireClass || f.BugClass == l.BugClass
+}
+
+type LabelScore struct {
+	Label  Label
+	Caught int // runs in which a finding matched
+}
+
+type CaseScore struct {
+	ID, Kind string
+	Runs     int // scored runs
+	Failed   int
+	Labels   []LabelScore
+	Findings int // across scored runs
+	Noise    int // findings matching no label, across scored runs
+}
+
+// Flaky reports labels found in some scored runs but not all of them.
+func (c CaseScore) Flaky() int {
+	n := 0
+	for _, l := range c.Labels {
+		if l.Caught > 0 && l.Caught < c.Runs {
+			n++
+		}
+	}
+	return n
+}
+
+type RepeatReport struct {
+	Cases                        []CaseScore
+	ScoredRuns, FailedRuns       int
+	Recall, RecallMin, RecallMax float64 // over runs; Min and Max are across whole-set runs
+	Precision                    float64
+	NoisePerCleanRun             float64
+	FlakyLabels, MissedLabels    int
+	Labels                       int
+	CostMicrousd                 int64
+	MedianLatency                time.Duration
+}
+
+// ScoreRepeat scores every run against the dataset. Recall is the share of
+// labelled bugs found, averaged over scored runs, and RecallMin/RecallMax show
+// the spread between whole-set runs. Precision is the share of findings on
+// labelled cases that matched a label; findings on clean cases are noise.
+func ScoreRepeat(dataset RepeatDataset, results []RunResult, options MatchOptions) (RepeatReport, error) {
+	if err := dataset.Validate(); err != nil {
+		return RepeatReport{}, err
+	}
+	byID := map[string]RepeatCase{}
+	for _, c := range dataset.Cases {
+		byID[c.ID] = c
+	}
+	scores := map[string]*CaseScore{}
+	for _, c := range dataset.Cases {
+		cs := &CaseScore{ID: c.ID, Kind: c.Kind}
+		for _, l := range c.Labels {
+			cs.Labels = append(cs.Labels, LabelScore{Label: l})
+		}
+		scores[c.ID] = cs
+	}
+	type tally struct{ caught, labels int }
+	perRun := map[int]*tally{}
+	var report RepeatReport
+	var matched, findings, cleanRuns, cleanNoise int
+	var latencies []time.Duration
+	for _, r := range results {
+		c, ok := byID[r.CaseID]
+		if !ok {
+			return RepeatReport{}, fmt.Errorf("result for unknown case %q", r.CaseID)
+		}
+		cs := scores[r.CaseID]
+		report.CostMicrousd += r.CostMicrousd
+		if r.Error != "" {
+			cs.Failed++
+			report.FailedRuns++
+			continue
+		}
+		cs.Runs++
+		report.ScoredRuns++
+		latencies = append(latencies, r.Latency)
+		t := perRun[r.Run]
+		if t == nil {
+			t = &tally{}
+			perRun[r.Run] = t
+		}
+		for i, l := range c.Labels {
+			t.labels++
+			for _, f := range r.Findings {
+				if options.matches(f, l) {
+					cs.Labels[i].Caught++
+					t.caught++
+					break
+				}
+			}
+		}
+		for _, f := range r.Findings {
+			hit := false
+			for _, l := range c.Labels {
+				if options.matches(f, l) {
+					hit = true
+					break
+				}
+			}
+			cs.Findings++
+			if !hit {
+				cs.Noise++
+			}
+			if c.Kind == "clean" {
+				cleanNoise++
+			} else {
+				findings++
+				if hit {
+					matched++
+				}
+			}
+		}
+		if c.Kind == "clean" {
+			cleanRuns++
+		}
+	}
+	var caught, labelRuns int
+	first := true
+	for _, t := range perRun {
+		caught += t.caught
+		labelRuns += t.labels
+		if t.labels == 0 {
+			continue
+		}
+		rate := float64(t.caught) / float64(t.labels)
+		if first || rate < report.RecallMin {
+			report.RecallMin = rate
+		}
+		if first || rate > report.RecallMax {
+			report.RecallMax = rate
+		}
+		first = false
+	}
+	if labelRuns > 0 {
+		report.Recall = float64(caught) / float64(labelRuns)
+	}
+	if findings > 0 {
+		report.Precision = float64(matched) / float64(findings)
+	}
+	if cleanRuns > 0 {
+		report.NoisePerCleanRun = float64(cleanNoise) / float64(cleanRuns)
+	}
+	for _, c := range dataset.Cases {
+		cs := scores[c.ID]
+		for _, l := range cs.Labels {
+			report.Labels++
+			switch {
+			case cs.Runs > 0 && l.Caught == 0:
+				report.MissedLabels++
+			case l.Caught > 0 && l.Caught < cs.Runs:
+				report.FlakyLabels++
+			}
+		}
+		report.Cases = append(report.Cases, *cs)
+	}
+	sort.Slice(latencies, func(i, j int) bool { return latencies[i] < latencies[j] })
+	if n := len(latencies); n > 0 {
+		report.MedianLatency = latencies[n/2]
+		if n%2 == 0 {
+			report.MedianLatency = (latencies[n/2-1] + latencies[n/2]) / 2
+		}
+	}
+	return report, nil
+}
+
+// Markdown renders the report for a person to read. It states the sample size
+// because a score from a handful of runs is a sketch, not a measurement.
+func (r RepeatReport) Markdown() string {
+	var b strings.Builder
+	fmt.Fprintf(&b, "# Review evaluation\n\n%d scored runs over %d cases (%d failed runs not scored). Cost $%.4f.\n\n", r.ScoredRuns, len(r.Cases), r.FailedRuns, float64(r.CostMicrousd)/1e6)
+	if r.ScoredRuns == 0 {
+		b.WriteString("Nothing was scored.\n")
+		return b.String()
+	}
+	fmt.Fprintf(&b, "- **Recall** %.0f%% of labelled bugs found per run (best run %.0f%%, worst run %.0f%%)\n", r.Recall*100, r.RecallMax*100, r.RecallMin*100)
+	fmt.Fprintf(&b, "- **Precision** %.0f%% of findings on bug cases matched a label\n", r.Precision*100)
+	fmt.Fprintf(&b, "- **Noise on clean changes** %.2f findings per clean run\n", r.NoisePerCleanRun)
+	fmt.Fprintf(&b, "- **Unstable bugs** %d of %d labels were found in some runs but not all; **never found** %d\n", r.FlakyLabels, r.Labels, r.MissedLabels)
+	fmt.Fprintf(&b, "- Median review time %s\n\n", r.MedianLatency.Round(time.Second))
+	b.WriteString("| Case | Kind | Found in runs | Findings | Noise |\n| --- | --- | --- | --- | --- |\n")
+	for _, c := range r.Cases {
+		found := "-"
+		if len(c.Labels) > 0 {
+			parts := make([]string, len(c.Labels))
+			for i, l := range c.Labels {
+				parts[i] = fmt.Sprintf("%d/%d", l.Caught, c.Runs)
+			}
+			found = strings.Join(parts, ", ")
+		}
+		fmt.Fprintf(&b, "| %s | %s | %s | %d | %d |\n", c.ID, c.Kind, found, c.Findings, c.Noise)
+	}
+	return b.String()
+}

diff --git a/internal/hosted/eval/repeat_test.go b/internal/hosted/eval/repeat_test.go
new file mode 100644
index 0000000..9454b01
--- /dev/null
+++ b/internal/hosted/eval/repeat_test.go
@@ -0,0 +1,153 @@
+package eval
+
+import (
+	"strings"
+	"testing"
+	"time"
+)
+
+var (
+	shaA = strings.Repeat("a", 40)
+	shaB = strings.Repeat("b", 40)
+)
+
+func testRepeatDataset() RepeatDataset {
+	return RepeatDataset{Version: 1, Cases: []RepeatCase{
+		{ID: "seed-1", Kind: "seeded", BaseSHA: shaA, HeadSHA: shaB, Labels: []Label{{Path: "a.ts", BugClass: "logic", StartLine: 10, EndLine: 12}}},
+		{ID: "seed-2", Kind: "seeded", BaseSHA: shaA, HeadSHA: shaB, Labels: []Label{{Path: "b.ts", BugClass: "logic", StartLine: 5, EndLine: 5}}},
+		{ID: "clean-1", Kind: "clean", BaseSHA: shaA, HeadSHA: shaB},
+	}}
+}
+
+func find(path string, start, end int) Finding {
+	return Finding{Path: path, StartLine: start, EndLine: end}
+}
+
+func TestScoreRepeatMeasuresRecallPrecisionNoiseAndVariance(t *testing.T) {
+	results := []RunResult{
+		// run 1: finds both bugs, one extra finding on seed-1, noise on the clean case
+		{CaseID: "seed-1", Run: 1, Findings: []Finding{find("a.ts", 11, 11), find("a.ts", 90, 90)}, CostMicrousd: 1000, Latency: 10 * time.Second},
+		{CaseID: "seed-2", Run: 1, Findings: []Finding{find("b.ts", 5, 5)}, CostMicrousd: 1000, Latency: 20 * time.Second},
+		{CaseID: "clean-1", Run: 1, Findings: []Finding{find("c.ts", 1, 1)}, CostMicrousd: 1000, Latency: 30 * time.Second},
+		// run 2: misses seed-2 entirely
+		{CaseID: "seed-1", Run: 2, Findings: []Finding{find("a.ts", 10, 10)}, CostMicrousd: 1000, Latency: 10 * time.Second},
+		{CaseID: "seed-2", Run: 2, CostMicrousd: 1000, Latency: 20 * time.Second},
+		{CaseID: "clean-1", Run: 2, CostMicrousd: 1000, Latency: 30 * time.Second},
+	}
+	report, err := ScoreRepeat(testRepeatDataset(), results, MatchOptions{LineSlack: 0})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if report.ScoredRuns != 6 || report.Recall != 0.75 || report.RecallMax != 1 || report.RecallMin != 0.5 {
+		t.Fatalf("recall=%v min=%v max=%v runs=%d", report.Recall, report.RecallMin, report.RecallMax, report.ScoredRuns)
+	}
+	// bug-case findings: 4 (a.ts:11, a.ts:90, b.ts:5, a.ts:10); 3 matched.
+	if report.Precision != 0.75 {
+		t.Fatalf("precision=%v", report.Precision)
+	}
+	if report.NoisePerCleanRun != 0.5 {
+		t.Fatalf("clean noise=%v", report.NoisePerCleanRun)
+	}
+	if report.FlakyLabels != 1 || report.MissedLabels != 0 || report.Labels != 2 {
+		t.Fatalf("flaky=%d missed=%d labels=%d", report.FlakyLabels, report.MissedLabels, report.Labels)
+	}
+	if report.CostMicrousd != 6000 || report.MedianLatency != 20*time.Second {
+		t.Fatalf("cost=%d latency=%v", report.CostMicrousd, report.MedianLatency)
+	}
+	if got := report.Cases[1].Labels[0]; got.Caught != 1 {
+		t.Fatalf("seed-2 caught %d of 2 runs", got.Caught)
+	}
+	if report.Cases[0].Flaky() != 0 || report.Cases[1].Flaky() != 1 {
+		t.Fatal("seed-1 is stable, seed-2 is flaky")
+	}
+}
+
+func TestScoreRepeatLeavesFailedRunsOutOfEveryScore(t *testing.T) {
+	results := []RunResult{
+		{CaseID: "seed-1", Run: 1, Findings: []Finding{find("a.ts", 10, 10)}},
+		{CaseID: "seed-1", Run: 2, Error: "provider outage"},
+		{CaseID: "seed-2", Run: 1, Error: "provider outage"},
+	}
+	report, err := ScoreRepeat(testRepeatDataset(), results, MatchOptions{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if report.FailedRuns != 2 || report.ScoredRuns != 1 {
+		t.Fatalf("failed=%d scored=%d", report.FailedRuns, report.ScoredRuns)
+	}
+	// seed-2 had no scored run, so it is neither missed nor flaky.
+	if report.MissedLabels != 0 || report.FlakyLabels != 0 || report.Recall != 1 {
+		t.Fatalf("an outage must not look like a miss: %+v", report)
+	}
+}
+
+func TestMatchOptionsLineSlackAndBugClass(t *testing.T) {
+	label := Label{Path: "a.ts", BugClass: "logic", StartLine: 10, EndLine: 12}
+	if (MatchOptions{}).matches(find("a.ts", 14, 14), label) {
+		t.Fatal("no slack: line 14 is outside 10-12")
+	}
+	if !(MatchOptions{LineSlack: 3}).matches(find("a.ts", 14, 14), label) {
+		t.Fatal("slack 3 should reach line 14")
+	}
+	if (MatchOptions{LineSlack: 3}).matches(find("a.ts", 16, 16), label) {
+		t.Fatal("slack 3 must not reach line 16")
+	}
+	if (MatchOptions{LineSlack: 3}).matches(find("other.ts", 11, 11), label) {
+		t.Fatal("a different file never matches")
+	}
+	f := Finding{Path: "a.ts", BugClass: "security", StartLine: 11, EndLine: 11}
+	if (MatchOptions{RequireClass: true}).matches(f, label) || !(MatchOptions{}).matches(f, label) {
+		t.Fatal("class is checked only when required")
+	}
+}
+
+func TestScoreRepeatReportsNeverFoundBugs(t *testing.T) {
+	report, err := ScoreRepeat(testRepeatDataset(), []RunResult{
+		{CaseID: "seed-1", Run: 1}, {CaseID: "seed-1", Run: 2},
+	}, MatchOptions{})
+	if err != nil || report.MissedLabels != 1 || report.Recall != 0 {
+		t.Fatalf("report=%+v err=%v", report, err)
+	}
+	if _, err := ScoreRepeat(testRepeatDataset(), []RunResult{{CaseID: "nope", Run: 1}}, MatchOptions{}); err == nil {
+		t.Fatal("a result for an unknown case must be rejected")
+	}
+}
+
+func TestRepeatDatasetValidation(t *testing.T) {
+	good := `{"version":1,"cases":[{"id":"c","kind":"clean","base_sha":"` + shaA + `","head_sha":"` + shaB + `"}]}`
+	if _, err := DecodeRepeat([]byte(good)); err != nil {
+		t.Fatal(err)
+	}
+	bad := map[string]string{
+		"clean with labels": `{"version":1,"cases":[{"id":"c","kind":"clean","base_sha":"` + shaA + `","head_sha":"` + shaB + `","labels":[{"path":"a","bug_class":"x","start_line":1,"end_line":1}]}]}`,
+		"seeded no labels":  `{"version":1,"cases":[{"id":"c","kind":"seeded","base_sha":"` + shaA + `","head_sha":"` + shaB + `"}]}`,
+		"short sha":         `{"version":1,"cases":[{"id":"c","kind":"clean","base_sha":"abc","head_sha":"` + shaB + `"}]}`,
+		"same sha":          `{"version":1,"cases":[{"id":"c","kind":"clean","base_sha":"` + shaA + `","head_sha":"` + shaA + `"}]}`,
+		"unknown kind":      `{"version":1,"cases":[{"id":"c","kind":"weird","base_sha":"` + shaA + `","head_sha":"` + shaB + `"}]}`,
+		"unknown field":     `{"version":1,"cases":[{"id":"c","kind":"clean","base_sha":"` + shaA + `","head_sha":"` + shaB + `","source":"code"}]}`,
+		"no cases":          `{"version":1,"cases":[]}`,
+		"duplicate id":      `{"version":1,"cases":[{"id":"c","kind":"clean","base_sha":"` + shaA + `","head_sha":"` + shaB + `"},{"id":"c","kind":"clean","base_sha":"` + shaA + `","head_sha":"` + shaB + `"}]}`,
+		"bad label range":   `{"version":1,"cases":[{"id":"c","kind":"seeded","base_sha":"` + shaA + `","head_sha":"` + shaB + `","labels":[{"path":"a","bug_class":"x","start_line":5,"end_line":2}]}]}`,
+	}
+	for name, input := range bad {
+		if _, err := DecodeRepeat([]byte(input)); err == nil {
+			t.Errorf("%s was accepted", name)
+		}
+	}
+}
+
+func TestRepeatMarkdownStatesSampleSizeAndFlakiness(t *testing.T) {
+	report, _ := ScoreRepeat(testRepeatDataset(), []RunResult{
+		{CaseID: "seed-1", Run: 1, Findings: []Finding{find("a.ts", 10, 10)}},
+		{CaseID: "seed-1", Run: 2},
+	}, MatchOptions{})
+	md := report.Markdown()
+	for _, want := range []string{"2 scored runs", "1/2", "Unstable bugs", "Recall"} {
+		if !strings.Contains(md, want) {
+			t.Fatalf("markdown lacks %q:\n%s", want, md)
+		}
+	}
+	if empty := (RepeatReport{}).Markdown(); !strings.Contains(empty, "Nothing was scored") {
+		t.Fatal(empty)
+	}
+}
